// clang-format off

#include "maul-rhi/base.h"

const char* mrhiDiagnosticText(mrhiDiagnosticCode code)
{
    switch (code)
    {
    case mrhi_diagnosticNullArgument:
        return "A required pointer is NULL, or an array is NULL with a nonzero count.";
    case mrhi_diagnosticDefHeader:
        return "A def lacks its cookie (start from its default def), carries a malformed extension chain or one deeper than the chainDepth limit, or a label that is not UTF-8 of at most MRHI_LABEL_BYTES.";
    case mrhi_diagnosticAdapterRequestDef:
        return "An adapter request def is NULL, lacks its cookie or names an unknown power preference.";
    case mrhi_diagnosticInstanceHasDevices:
        return "An instance was destroyed while devices made on it live; nothing was destroyed.";
    case mrhi_diagnosticSurfaceSource:
        return "A surface def names no surface source, or more than one.";
    case mrhi_diagnosticSurfaceConfig:
        return "A surface config names an unknown format, primaries, transfer or range, or a view format that is not its format's twin.";
    case mrhi_diagnosticNativeCommands:
        return "Native commands set without a command buffer, or on a pass not added as native.";
    case mrhi_diagnosticRecordedInNativePass:
        return "A command recorded through the library in a native pass, whose commands are the program's own.";
    case mrhi_diagnosticNativePassDef:
        return "A native pass def with targets, query sets or a heap, or with an access that resolves queries or names a resource that is not imported.";
    case mrhi_diagnosticPassEndOpen:
        return "A pass ended with a debug group or a query still open.";
    case mrhi_diagnosticRenderStateOutsideRenderPass:
        return "A draw, a graphics pipeline or other draw state recorded in a pass without targets.";
    case mrhi_diagnosticComputeOutsideComputePass:
        return "A dispatch, a compute pipeline or a query resolve recorded in a pass that is not a compute pass.";
    case mrhi_diagnosticTransferInRenderPass:
        return "A copy, clear, upload or readback recorded in a pass with targets.";
    case mrhi_diagnosticGraphicsPipelineMismatch:
        return "A graphics pipeline whose targets differ from the pass's, which writes depth or stencil the pass only reads, or which uses a heap the pass has none of.";
    case mrhi_diagnosticComputePipelineHeap:
        return "A compute pipeline that uses a heap, set in a pass without one.";
    case mrhi_diagnosticBindingsTable:
        return "Bindings set in a transfer pass, or for a table past the bindingTables limit.";
    case mrhi_diagnosticBindingsCount:
        return "A binding count that is not the number of slots the pipeline's reflection gives the table.";
    case mrhi_diagnosticBindingsSlot:
        return "A binding naming a slot the table lacks, or one already bound in the same call.";
    case mrhi_diagnosticBindingResource:
        return "A binding whose resource does not fit its slot: its kind, usage, range, format or the access the pass declares.";
    case mrhi_diagnosticRootBlock:
        return "A root block set in a transfer pass, empty, or at an offset or size not a multiple of 4.";
    case mrhi_diagnosticVertexBufferSlot:
        return "A vertex buffer set at a slot past the vertexBuffers limit.";
    case mrhi_diagnosticVertexBufferTooSmall:
        return "A draw reading vertices or instances past the end of a vertex buffer it uses.";
    case mrhi_diagnosticIndexBufferFormat:
        return "An index buffer set with an unknown format.";
    case mrhi_diagnosticDispatchSize:
        return "A dispatch of more workgroups in a dimension than the workgroupsPerDimension limit.";
    case mrhi_diagnosticIndirectCountLimit:
        return "A counted indirect draw whose maxCount is zero or past MRHI_INDIRECT_DRAWS.";
    case mrhi_diagnosticViewport:
        return "A viewport wider or taller than the textureDimension2d limit, outside twice that range, or with depths outside [0, 1] or in reverse order.";
    case mrhi_diagnosticScissor:
        return "A scissor rectangle reaching past the pass's targets.";
    case mrhi_diagnosticBlendConstant:
        return "A blend constant that is not finite.";
    case mrhi_diagnosticDebugLabel:
        return "A debug label that is empty, not UTF-8, or longer than MRHI_LABEL_BYTES.";
    case mrhi_diagnosticDebugGroupUnderflow:
        return "A debug group popped with none open.";
    case mrhi_diagnosticResourceKind:
        return "A texture given where a buffer is wanted, or a buffer where a texture is.";
    case mrhi_diagnosticBufferTextureCopy:
        return "A copy between a buffer and a texture whose layout the buffer cannot hold: an offset not a multiple of the texel block's bytes (4 for depth), bytes per row not a multiple of 256, rows or images shorter than the copy needs, or a region past the buffer.";
    case mrhi_diagnosticTextureRegion:
        return "A texture region off the format's blocks or past the mip, of a multisampled texture, or of an aspect that cannot be copied, or a buffer named as the texture.";
    case mrhi_diagnosticCopyTextureMismatch:
        return "A texture copy between formats that are neither equal nor sRGB twins, between sample counts that differ, or naming one aspect of a format that has two.";
    case mrhi_diagnosticWriteTextureLayout:
        return "A texture write whose layout the bytes cannot hold: rows or images shorter than the write needs, or a region past the bytes given.";
    case mrhi_diagnosticFrameToken:
        return "A frame token this device never returned.";
    case mrhi_diagnosticTransientUsage:
        return "A transient resource declared with a usage; the frame derives its usages from the passes' accesses.";
    case mrhi_diagnosticSealNotImported:
        return "A resource sealed or unsealed that is not imported.";
    case mrhi_diagnosticSealTexture:
        return "A texture sealed without sampled usage, or an adopted image, which rests as a target.";
    case mrhi_diagnosticHeapDef:
        return "A heap def with no entries.";
    case mrhi_diagnosticHeapIndex:
        return "A heap index past the heap's entries or samplers.";
    case mrhi_diagnosticHeapEntry:
        return "A heap entry of an unknown kind.";
    case mrhi_diagnosticHeapView:
        return "A heap entry's view without the usage its kind needs, a storage view of more than one mip, or a sampled view marked writable.";
    case mrhi_diagnosticHeapBuffer:
        return "A heap entry's buffer without storage usage, or a range misaligned, empty, not a multiple of 4 or past the buffer.";
    case mrhi_diagnosticQuerySetDef:
        return "A query set def of an unknown type, or of zero or too many queries.";
    case mrhi_diagnosticOcclusionQuery:
        return "An occlusion query begun in a pass without an occlusion set, while one is open, past the set or written twice in a frame; or ended with none open.";
    case mrhi_diagnosticStatisticsQuery:
        return "A statistics query begun outside a graphics-class pass of one view, while one is open, on a set of another type, past the set or written twice in a frame; or ended with none open.";
    case mrhi_diagnosticSamplerDef:
        return "A sampler def with an unknown filter, address mode or compare function, a negative or reversed level of detail range, or anisotropy outside 1 to 16 or above 1 without linear filtering.";
    case mrhi_diagnosticBufferSize:
        return "A buffer size of zero or not a multiple of 4.";
    case mrhi_diagnosticBufferUsage:
        return "A buffer def with no usage, or an unknown one.";
    case mrhi_diagnosticShaderBytes:
        return "Shader bytes that are NULL or not 8-byte aligned.";
    case mrhi_diagnosticShaderContainer:
        return "Shader bytes that are not a well-formed container: its bounds, version, digest or reflection.";
    case mrhi_diagnosticTextureUsage:
        return "A texture def with a usage that is unknown or that its format, kind or sample count cannot take.";
    case mrhi_diagnosticTextureAdopt:
        return "A texture adopting a Vulkan image without an image, or without render target usage.";
    case mrhi_diagnosticViewDef:
        return "A view def with an unknown kind or aspect.";
    case mrhi_diagnosticViewRange:
        return "A view whose mips, layers, format, aspect or kind its texture cannot give.";
    case mrhi_diagnosticDriverRequestTags:
        return "A request reached the driver past the notifications limit, so its answer could not be matched.";
    case mrhi_diagnosticDriverUnaskedAnswer:
        return "A driver answered a request it was never asked, or answered one twice.";
    case mrhi_diagnosticDriverEventsOverrun:
        return "A driver reported more events than the room it was given; the layer kept the room's worth.";
    case mrhi_diagnosticDriverEventTag:
        return "A device driver reported an event without a tag that is not a device loss.";
    case mrhi_diagnosticDriverAdapter:
        return "A driver listed an adapter with a zero or repeated handle, a name longer than MRHI_ADAPTER_NAME_BYTES, or an unknown kind.";
    case mrhi_diagnosticDriverSampleCounts:
        return "A driver reported format caps naming sample counts other than 1, 2 and 4.";
    case mrhi_diagnosticDriverZeroHandle:
        return "A driver reported success for an object, surface or surface image with a zero handle.";
    case mrhi_diagnosticDriverDeviceHandshake:
        return "A driver made a device whose vtable fails the SPI version and size handshake.";
    case mrhi_diagnosticDriverTimestampPeriod:
        return "A driver reported a negative timestamp period.";
    case mrhi_diagnosticDriverMemoryAlignment:
        return "A driver reported a memory alignment of zero or not a power of two.";
    case mrhi_diagnosticDriverFrameWalk:
        return "A submitted frame failed the layer's walk: a handle, payload or range no driver could translate.";
    case mrhi_diagnosticPipelineEntry:
        return "A pipeline def names an entry point its shader lacks for the stage, gives a fragment entry length without a name, or names no vertex entry.";
    case mrhi_diagnosticPipelineConstants:
        return "A pipeline def's constant values name an id the shader lacks, give one twice, hold a value its type cannot, or leave out one without a default.";
    case mrhi_diagnosticGraphicsVertex:
        return "A graphics pipeline's vertex state is malformed: its buffers or attributes, two attributes at one location, or a vertex input with no attribute of its scalar class.";
    case mrhi_diagnosticGraphicsPrimitive:
        return "A graphics pipeline's primitive state has an unknown value, a strip index format for a list, or more than one view without multiview.";
    case mrhi_diagnosticGraphicsDepthStencil:
        return "A graphics pipeline's depth and stencil state has an unknown value, an aspect's fields set without the aspect in the format, a bias that is not finite or set for points and lines, or no depth format while the fragment entry writes depth.";
    case mrhi_diagnosticGraphicsTargets:
        return "A graphics pipeline's color targets are more than MRHI_COLOR_TARGETS, present without a fragment entry, malformed (format, blend or writes), not written by the fragment entry's outputs as their types allow, or absent with no depth either.";
    case mrhi_diagnosticGraphicsMultisample:
        return "A graphics pipeline's sample count is not a power of two, or alpha to coverage is asked single-sampled, without a first target that has alpha, or while the fragment entry writes the sample mask.";
    case mrhi_diagnosticGraphicsInterface:
        return "A graphics pipeline's fragment input has no vertex output of the same location, type and interpolation, or a point list leaves no room for its point size.";
    case mrhi_diagnosticChainedStruct:
        return "A chained struct the def carries is malformed: an adopted Vulkan object that is NULL, or an extension list that is not a list of names.";
    case mrhi_diagnosticDeviceLimits:
        return "A device def's device limits include a zero, fewer than 2 notifications, a command arena under one chunk, or readback bytes not a multiple of 512.";
    case mrhi_diagnosticLimitsFloor:
        return "A device def asks for limits below the floor every adapter reaches.";
    case mrhi_diagnosticAllocator:
        return "An allocator with one function set and the other not.";
    case mrhi_diagnosticPipelineCacheBytes:
        return "A pipeline cache size given without its bytes.";
    case mrhi_diagnosticTextureFormat:
        return "A texture def names an unknown format.";
    case mrhi_diagnosticTextureSize:
        return "A texture def's size or layers do not fit its kind and its format's block, or its mips are more than a full chain.";
    case mrhi_diagnosticTextureSamples:
        return "A texture def's sample count is not 1, 2 or 4, or several samples are asked for a texture that is not 2D with one mip.";
    case mrhi_diagnosticTextureViewFormats:
        return "A texture def's view format is neither unused nor its format's twin.";
    case mrhi_diagnosticTransferAlignment:
        return "An offset or size not a multiple of what the command needs: 4 for buffer copies, clears, uploads, readbacks, vertex buffers and indirect arguments, the index size for index buffers, 256 for query resolves.";
    case mrhi_diagnosticTransferRange:
        return "A range reaching past the end of its buffer, or past its query set.";
    case mrhi_diagnosticUndeclaredAccess:
        return "A command reaching a resource the pass declares no covering access of the kind it needs.";
    case mrhi_diagnosticPassClass:
        return "A pass def with an unknown pass class.";
    case mrhi_diagnosticPassColorTargets:
        return "A pass def with more than MRHI_COLOR_TARGETS color targets.";
    case mrhi_diagnosticPassViews:
        return "A pass def with several views on a native pass or on one without targets.";
    case mrhi_diagnosticPassQueries:
        return "A pass def's query sets do not fit: an occlusion set that is not one or on a pass without targets, or timestamps that are not a graphics pass's two different queries, in range and not yet written this frame.";
    case mrhi_diagnosticPassUses:
        return "A pass def's accesses or targets do not fit: a kind the resource's usage lacks, a range past it, a write to a sealed resource, targets whose sizes, samples, mips or layers disagree, uses that conflict within the pass, or a read of a declared resource no earlier pass wrote.";
    default:
        return "An unknown diagnostic code.";
    }
}
